// Hand-written `bull` stub for the flowatlas fixture suite.
//
// It exists for one declaration. `Job` is the parameter type of every bull-era
// `@Process` handler, and it is exported by this package and by no other;
// `@nestjs/bull` exports the decorators and nothing else. The suite used to
// fold `Job` into the `@nestjs/bull` stub to ship one file fewer, which meant
// the fixture imported a name the real package has never had. A stub may
// declare less than the library it stands for; it may not declare something the
// library does not declare at all, because then the fixture is testing the stub.
//
// Nothing here is ever a call receiver, so no adapter reads it. What has to be
// true is the specifier the import names.

export interface Job<T = unknown> {
  readonly id: string;
  readonly name: string;
  readonly data: T;
}
